"""Certify the tail-vanishing Escher staircase in the ring of integer sequences."""
from __future__ import annotations
from typing import Dict

Sequence_ = Dict[int, int]

def in_tail_zero_ideal(f: Sequence_, n: int) -> bool:
    """f in S_n  iff  f_k = 0 for all k >= n."""
    return all(index < n for index, value in f.items() if value != 0)

def certify_staircase(depth: int = 8) -> None:
    for n in range(depth):
        e = {n: 1}  # indicator e_n: the strict-jump witness
        assert in_tail_zero_ideal(e, n + 1) and not in_tail_zero_ideal(e, n)
        print(f"S_{n} < S_{n+1} strict, witnessed by e_{n}")
    assert in_tail_zero_ideal({}, 0) and not in_tail_zero_ideal({0: 1}, 0)
    print("S_0 = {0}; meet of all S_n = S_0 = {0}: the staircase loops back.")

if __name__ == "__main__":
    certify_staircase()

"""Certify the variable staircase V_n = <x_0,...,x_{n-1}> via monomial divisibility."""
from __future__ import annotations
from typing import Set, Tuple

Monomial = Tuple[Tuple[int, int], ...]

def in_variable_ideal(m: Monomial, gens: Set[int]) -> bool:
    """A monomial lies in the monomial ideal <x_i : i in gens> iff some such x_i divides it."""
    return any(exp > 0 and idx in gens for idx, exp in m)

def certify_variable_staircase(depth: int = 8) -> None:
    for n in range(depth):
        xn: Monomial = ((n, 1),)
        assert in_variable_ideal(xn, set(range(n + 1)))       # x_n in V_{n+1}
        assert not in_variable_ideal(xn, set(range(n)))        # x_n not in V_n
        print(f"x_{n} in V_{n+1} but not V_{n}  =>  V_{n} < V_{n+1}")
    print("V_0 = <empty> = {0}; the tower loops back to the zero ideal.")

if __name__ == "__main__":
    certify_variable_staircase()

